&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;138rv-0-0&quot;&gt;&lt;strong&gt;&lt;span data-offset-key=&quot;138rv-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;What You’ll Do&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;p&quot; data-block=&quot;true&quot; data-editor=&quot;653s3&quot; data-offset-key=&quot;8hsqt-0-0&quot;&gt;
